    case 9:
        dst_p->eeprom = unpack_right_shift_u8(src_p[1], 0u, 0xffu);
        break;

    case 10:
        flap_l_offset = unpack_right_shift_u16(src_p[1], 0u, 0xffu);
        flap_l_offset |= unpack_left_shift_u16(src_p[2], 8u, 0xffu);
        dst_p->flap_l_offset = (int16_t)flap_l_offset;
        break;

    case 11:
        flap_r_offset = unpack_right_shift_u16(src_p[1], 0u, 0xffu);
        flap_r_offset |= unpack_left_shift_u16(src_p[2], 8u, 0xffu);
        dst_p->flap_r_offset = (int16_t)flap_r_offset;
        break;

    case 12:
        dst_p->flap_l_reverse = unpack_right_shift_u8(src_p[1], 0u, 0xffu);
        break;

    case 13:
        dst_p->flap_r_reverse = unpack_right_shift_u8(src_p[1], 0u, 0xffu);
