        break;

    case 16:
        dst_p->regen_enable = unpack_right_shift_u8(src_p[1], 0u, 0xffu);
        break;

    case 17:
        dst_p->regen_max_trq = unpack_right_shift_u8(src_p[1], 0u, 0xffu);
