        dst_p->regen_max_cell_volt |= unpack_left_shift_u16(src_p[2], 8u, 0xffu);
        break;

    case 19:
        dst_p->regen_max_cell_temp = unpack_right_shift_u8(src_p[1], 0u, 0xffu);
        break;

    case 20:
        regen_max_current = unpack_right_shift_u16(src_p[1], 0u, 0xffu);
        regen_max_current |= unpack_left_shift_u16(src_p[2], 8u, 0xffu);
        dst_p->regen_max_current = (int16_t)regen_max_current;
        break;

    case 21:
        dst_p->regen_thr_speed = unpack_right_shift_u8(src_p[1], 0u, 0xffu);
        break;

    case 22:
        dst_p->regen_thr_rpm = unpack_right_shift_u16(src_p[1], 0u, 0xffu);
        dst_p->regen_thr_rpm |= unpack_left_shift_u16(src_p[2], 8u, 0xffu);
