        dst_p[3] |= pack_right_shift_u16(src_p->cell5, 4u, 0xffu);
        dst_p[4] |= pack_left_shift_u16(src_p->cell6, 0u, 0xffu);
        dst_p[5] |= pack_right_shift_u16(src_p->cell6, 8u, 0x0fu);
        break;

    case 2:
        dst_p[1] |= pack_left_shift_u16(src_p->cell7, 0u, 0xffu);
        dst_p[2] |= pack_right_shift_u16(src_p->cell7, 8u, 0x0fu);
        dst_p[2] |= pack_left_shift_u16(src_p->cell8, 4u, 0xf0u);
        dst_p[3] |= pack_right_shift_u16(src_p->cell8, 4u, 0xffu);
        dst_p[4] |= pack_left_shift_u16(src_p->cell9, 0u, 0xffu);
        dst_p[5] |= pack_right_shift_u16(src_p->cell9, 8u, 0x0fu);
        break;

    case 3:
        dst_p[1] |= pack_left_shift_u16(src_p->cell10, 0u, 0xffu);
        dst_p[2] |= pack_right_shift_u16(src_p->cell10, 8u, 0x0fu);
