        dst_p[2] |= pack_right_shift_u16(src_p->cell13, 8u, 0x0fu);
        dst_p[2] |= pack_left_shift_u16(src_p->cell14, 4u, 0xf0u);
        dst_p[3] |= pack_right_shift_u16(src_p->cell14, 4u, 0xffu);
