        dst_p[4] |= pack_left_shift_u16(src_p->cell9, 0u, 0xffu);
        dst_p[5] |= pack_right_shift_u16(src_p->cell9, 8u, 0x0fu);
        break;

    case 3:
        dst_p[1] |= pack_left_shift_u16(src_p->cell10, 0u, 0xffu);
        dst_p[2] |= pack_right_shift_u16(src_p->cell10, 8u, 0x0fu);
